import { useState } from "react";
import { ConfirmButton } from "@/shared/ui/controls/ConfirmButton";
import { Card } from "@/shared/ui/data/Card";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row as LayoutRow } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

// Vendored from `@/features/settings/pages/SettingsControls` (unresolvable in this sandbox as a
// standalone import — that file's own promoted component only covers its ToggleRow export) — unchanged.
function SettingsRow({ label, hint, children }) {
  return (
    <LayoutRow gap={12} style={{ padding: "10px 0", borderBottom: "1px solid var(--border-soft)" }}>
      <Box style={{ flex: 1, minWidth: 0 }}>
        <Text as="div" size={13} style={{ fontFamily: "var(--sans)", color: "var(--fg)" }}>{label}</Text>
        {hint && <Text as="div" size={11} tone="dim" style={{ fontFamily: "var(--sans)", marginTop: 2 }}>{hint}</Text>}
      </Box>
      {children}
    </LayoutRow>
  );
}
function SettingsSelect({ value, options, onChange }) {
  return (
    // eslint-disable-next-line no-restricted-syntax -- vendored verbatim from the real SettingsControls helper
    <select
      value={value}
      onChange={(e) => { const raw = e.target.value; onChange(typeof value === "number" ? Number(raw) : raw); }}
      className="mono"
      style={{ fontSize: 11.5, background: "var(--bg-elev)", color: "var(--fg)", border: "1px solid var(--border)", borderRadius: 6, padding: "5px 8px", cursor: "pointer" }}
    >
      {options.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
    </select>
  );
}

// Preview-only stand-in for the real `useAppStore().perfConfig` — app-internal, unresolvable here.
const DEFAULT_PERF_CONFIG = { retentionHours: 24, maxDbMb: 50 };

export function PerfRetentionCard() {
  const [perfConfig, setPerfConfig] = useState(DEFAULT_PERF_CONFIG);
  const [clearStatus, setClearStatus] = useState<"idle" | "ok" | "err">("idle");

  const update = (patch) => {
    setPerfConfig({ ...perfConfig, ...patch });
  };

  const clearHistory = () => {
    setClearStatus("ok");
    setTimeout(() => setClearStatus("idle"), 2000);
  };

  return (
    <Card title="Metrics retention">
      <Stack gap={0}>
        <SettingsRow
          label="History retention"
          hint="Samples older than this are deleted from the database automatically."
        >
          <SettingsSelect
            value={perfConfig.retentionHours}
            options={[
              { label: "1 hour", value: 1 },
              { label: "6 hours", value: 6 },
              { label: "24 hours (default)", value: 24 },
              { label: "72 hours", value: 72 },
              { label: "Unlimited", value: 0 },
            ]}
            onChange={(v) => update({ retentionHours: v })}
          />
        </SettingsRow>

        <SettingsRow
          label="Max database size"
          hint="Prune oldest rows if the DB file exceeds this size. 0 = no limit."
        >
          <SettingsSelect
            value={perfConfig.maxDbMb}
            options={[
              { label: "10 MB", value: 10 },
              { label: "50 MB (default)", value: 50 },
              { label: "200 MB", value: 200 },
              { label: "No limit", value: 0 },
            ]}
            onChange={(v) => update({ maxDbMb: v })}
          />
        </SettingsRow>

        <SettingsRow
          label="Clear history"
          hint="Delete all stored samples from the database and the in-memory ring buffer."
        >
          <Box style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <ConfirmButton
              label="Clear history"
              armedLabel="Click again to confirm"
              onConfirm={clearHistory}
            />
            {clearStatus === "ok" && (
              <Text as="span" mono size="sm" tone="accent">Cleared</Text>
            )}
            {clearStatus === "err" && (
              <Text as="span" mono size="sm" tone="danger">Failed</Text>
            )}
          </Box>
        </SettingsRow>
      </Stack>
    </Card>
  );
}
